int size = 1;
foreach (var q in queries) size = Math.Max(size, q[2] / 2);   // клетки помельче — меньше лишних проверок
var grid = new Dictionary<long, List<int>>();
for (int i = 0; i < points.Length; i++) {
    long key = Key(points[i][0] / size, points[i][1] / size);
    if (!grid.TryGetValue(key, out var bucket)) grid[key] = bucket = new List<int>();
    bucket.Add(i);
}
for (int j = 0; j < queries.Length; j++) {
    int x = queries[j][0], y = queries[j][1], r = queries[j][2], cx = x / size, cy = y / size;
    for (int gy = cy - 1; gy <= cy + 1; gy++)
        for (int gx = cx - 1; gx <= cx + 1; gx++)
            answer[j] += CountInside(grid, Key(gx, gy), points, x, y, r);
}
